const overview = $('Fetch Overview KPIs').first().json;
const jobStats = $('Fetch Job Stats').first().json;

const summaryText = `
# 🎯 JobHunter AI — Daily Summary Digest
**Date:** ${new Date().toISOString().split('T')[0]}

## Key Metrics
- **Total Discovered Jobs:** ${overview.total_jobs}
- **Discovered Today:** ${jobStats.discovered_today}
- **Qualified Matches:** ${overview.qualified_jobs}
- **Applications Sent:** ${overview.applications_submitted}
- **Pending Your Approval:** ${overview.pending_approvals}
- **Interview Invitations:** ${overview.interview_invitations}
- **Average Match Score:** ${overview.average_match_score}%
- **Conversion Rate:** ${overview.conversion_rate}%

Access Dashboard: https://jobs.solaymanbuilds.com
`;

return [{ json: { summary: summaryText, timestamp: new Date().toISOString() } }];
